function _getReserves()
        public
        view
        returns (uint256 rOther, uint256 rThis, uint256 balanceOther)
    {
        PancakeSwapPair mainPair = PancakeSwapPair(_mainPair);
        (uint r0, uint256 r1, ) = mainPair.getReserves();

        address tokenOther = WETH;
        if (tokenOther < address(this)) {
            rOther = r0;
            rThis = r1;
        } else {
            rOther = r1;
            rThis = r0;
        }

        balanceOther = IERC20(tokenOther).balanceOf(_mainPair);
    }

function calLiquidity(
        uint256 balanceA,
        uint256 amount,
        uint256 r0,
        uint256 r1
    ) public view returns (uint256 liquidity, uint256 feeToLiquidity) {
        uint256 pairTotalSupply = PancakeSwapPair(_mainPair).totalSupply();
        address feeTo = PancakeSwapFactory(swapRouter.factory()).feeTo();
        bool feeOn = feeTo != address(0);
        uint256 _kLast = PancakeSwapPair(_mainPair).kLast();
        if (feeOn) {
            if (_kLast != 0) {
                uint256 rootK = Math.sqrt(r0 * r1);
                uint256 rootKLast = Math.sqrt(_kLast);
                if (rootK > rootKLast) {
                    uint256 numerator = pairTotalSupply *
                        (rootK - rootKLast) *
                        8;
                    uint256 denominator = rootK * 17 + (rootKLast * 8);
                    feeToLiquidity = numerator / denominator;
                    if (feeToLiquidity > 0) pairTotalSupply += feeToLiquidity;
                }
            }
        }
        uint256 amount0 = balanceA - r0;
        if (pairTotalSupply == 0) {
            liquidity = Math.sqrt(amount0 * amount) - 1000;
        } else {
            liquidity = Math.min(
                (amount0 * pairTotalSupply) / r0,
                (amount * pairTotalSupply) / r1
            );
        }
    }

function _isAddLiquidity(
        uint256 amount
    ) public view returns (uint256 liquidity) {
        (uint256 rOther, uint256 rThis, uint256 balanceOther) = _getReserves();
        uint256 amountOther;
        if (rOther > 0 && rThis > 0) {
            amountOther = (amount * rOther) / rThis;
        }
        //isAddLP
        if (balanceOther >= rOther + amountOther) {
            (liquidity, ) = calLiquidity(balanceOther, amount, rOther, rThis);
        }
    }

function _isRemoveLiquidity(
        uint256 amount
    ) internal view returns (uint256 liquidity) {
        (uint256 rOther, , uint256 balanceOther) = _getReserves();
        //isRemoveLP
        if (balanceOther <= rOther) {
            liquidity =
                (amount * PancakeSwapPair(_mainPair).totalSupply()) /
                (balanceOf(_mainPair) - amount);
        }
    }

function _transfer(address from, address to, uint256 value) internal {
        if (from == address(0)) {
            revert ERC20InvalidSender(address(0));
        }
        if (to == address(0)) {
            revert ERC20InvalidReceiver(address(0));
        }

        // bool isSell;
        bool isTransfer;

        if (from != _mainPair &&  to != _mainPair) {
            isTransfer = true;
        }

        bool isRemove;
        bool isAdd;
        // bool a;
        // bool b;
        uint256 addLPLiquidity;
        if (to == _mainPair && msg.sender == ROUTER && tx.origin == from 
            && !(whiteList[from] || whiteList[to])) {
            addLPLiquidity = _isAddLiquidity(value);
            if (addLPLiquidity > 0 && !isContract(from)) {
                isAdd = true;
            }
        }

        uint256 removeLPLiquidity;
        if (from == _mainPair) {

            removeLPLiquidity = _isRemoveLiquidity(value);

            if (removeLPLiquidity > 0) {
                isRemove = true;
            }
        }
        // bool isAddLiq = _isAddLiquidity();
        // bool isRemoveLiq = _isRemoveLiquidity();
        bool isBuy = (from == _mainPair)  ;
        bool isSell = (to == _mainPair) ;

        // debugAddLiquidity();
        // debugRemoveLiquidity();

        emit DebugTransfer(
            from,
            to,
            value,
            _mainPair,
            isAdd,
            isRemove,
            isBuy,
            isSell
        );

        if (!_tradingEnabled) {
            // if (!(isTransfer || isAdd || isRemove )) {
            //     revert("Trading is disabled");
            // }
        }

        uint256 finalAmount = value;
        uint256 feeAmount;

        if ((isBuy || isSell) && !whiteList[from] && !whiteList[to]) {
            if(isBuy){
                feeAmount = (value * _buyFeeTax) / 100;
            }else{
               if (_endHighTaxTime == 0 || block.timestamp <= _endHighTaxTime) {
                    feeAmount = (value * _sellHighFeeTax) / 100;
                } else {
                    feeAmount = (value * _sellFeeTax) / 100;
                }
            }
        }

        if (feeAmount > 0) {
            finalAmount = value - feeAmount;
            _update(from, address(this), feeAmount);

            if (!swapping && isSell) {
                _swapAndReward();
            }
        }

        _update(from, to, finalAmount);
    }

function _update(address from, address to, uint256 value) internal virtual {
        if (from == address(0)) {
            // Overflow check required: The rest of the code assumes that totalSupply never overflows
            _totalSupply += value;
        } else {
            uint256 fromBalance = _balances[from];
            if (fromBalance < value) {
                revert ERC20InsufficientBalance(from, fromBalance, value);
            }
            unchecked {
                // Overflow not possible: value <= fromBalance <= totalSupply.
                _balances[from] = fromBalance - value;
            }
        }

        if (to == address(0)) {
            unchecked {
                // Overflow not possible: value <= totalSupply or value <= fromBalance <= totalSupply.
                _totalSupply -= value;
            }
        } else {
            unchecked {
                // Overflow not possible: balance + value is at most totalSupply, which we know fits into a uint256.
                _balances[to] += value;
            }
        }

        emit Transfer(from, to, value);
    }

function _approve(address owner, address spender, uint256 value) internal {
        _approve(owner, spender, value, true);
    }

function _approve(address owner, address spender, uint256 value) internal {
        _approve(owner, spender, value, true);
    }

function _spendAllowance(
        address owner,
        address spender,
        uint256 value
    ) internal virtual {
        uint256 currentAllowance = allowance(owner, spender);
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < value) {
                revert ERC20InsufficientAllowance(
                    spender,
                    currentAllowance,
                    value
                );
            }
            unchecked {
                _approve(owner, spender, currentAllowance - value, false);
            }
        }
    }

function setWhiteList(
        address[] memory addressList,
        bool w
    ) external onlyOwner {
        for (uint256 i = 0; i < addressList.length; i++) {
            whiteList[addressList[i]] = w;
        }
    }

function startTrading() external onlyOwner {
        require(_endHighTaxTime == 0, "Trading already started");
        _endHighTaxTime = block.timestamp + _highTaxDuration;
        _tradingEnabled = true;
    }

function _swapAndReward() internal swapLock {
        address[] memory path = new address[](2);

        path[0] = address(this);
        path[1] = WETH;
        uint256 balance = balanceOf(address(this));
        require(balance > 0, "No tokens to swap");

        _approve(address(this), ROUTER, balance);

        swapRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            balance,
            0,
            path,
            marketAddress,
            block.timestamp
        );

    }

function isContract(address _addr) private view returns (bool) {
        uint32 size;
        assembly {
            size := extcodesize(_addr)
        }
        return (size > 0);
    }
